/**
 * LEADFORGE V15 (Hybrid Base) 
 * Stripped of AI Intent to allow for AI Agent judgment.
 * Focus: Factual "Floor" Scoring.
 */

const results = [];

const getLeadData = () => {
  try { return $("Normalise Data").item.json; } catch (e) {
    try { return $("Normalise").item.json; } catch (e2) {
      return $input.all()[0].json; 
    }
  }
};

const lead = getLeadData();

// CIRCUIT BREAKER
if (!lead.email && !lead.work_email) {
  return [{ json: { error: "Invalid Lead: Missing Email", base_score: 0 } }];
}

for (const item of $input.all()) {
  const aiData = item.json; // This is the AI Research output
  let score = 0;

  // --- A. BUDGET (Max 35) ---
  const budget = Number(lead.budget_numeric_min) || 0;
  if (budget >= 500000) score += 35;
  else if (budget >= 100000) score += 25;
  else if (budget >= 25000) score += 10;

  // --- B. AUTHORITY (Max 20) ---
  const rawAuth = (lead.decision_authority || lead.job_role || "").toLowerCase().trim();
  const highLevel = /final|decision|ceo|founder|cto|vp|director|head|owner/i;
  const midLevel = /manager|lead|team|influencer/i;

  if (highLevel.test(rawAuth)) score += 20;
  else if (midLevel.test(rawAuth)) score += 12;

  // --- C. COMPANY SCALE (Max 15) ---
  const size = (lead.company_size || "").toString().trim();
  if (size.includes("500") || size.includes("10,000")) score += 15;
  else if (size.includes("201") || size.includes("51")) score += 10;
  else if (size.includes("11")) score += 5;

  // --- FINAL BASE CALCULATION ---
  // Max base score is 70. The AI Agent will provide the remaining 30.
  score = Math.min(70, Math.max(0, score));

  results.push({
    json: {
      ...lead,
      ...aiData,
      base_score: score,
      processed_at: new Date().toISOString()
    }
  });
}

return results;

/**
 * 110% ULTIMATE PRODUCTION NORMALIZER
 * Verified against: Sales Inquiry Form (V2 Final)
 * Status: ZERO-COMPROMISE PRODUCTION READY
 */

// --- 1. CORE UTILITIES ---
const clean = (v) => (typeof v === 'string' ? v.trim() : v);

// Fixes casing for professional CRM entry (e.g., "john doe" -> "John Doe")
const toTitleCase = (str) => {
  if (!str) return '';
  return str.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
};

// Ensures website URLs are valid for AI research and CRM clicking
const sanitizeUrl = (url) => {
  if (!url) return null;
  let u = clean(url).toLowerCase();
  if (!u.startsWith('http')) u = 'https://' + u;
  return u;
};

// Specialized Indian Phone Formatter
const formatPhone = (v) => {
  if (!v) return null;
  let p = String(v).replace(/[^\d]/g, '');
  if (p.length === 12 && p.startsWith('91')) p = p.substring(2);
  if (p.length === 11 && p.startsWith('0')) p = p.substring(1);
  return p.length === 10 ? p : v;
};

// Numeric Budget Extraction for Lead Scoring Node
function parseINR(val) {
  if (!val) return { min: 0, max: null, raw: 'Not Specified' };
  const str = String(val).replace(/,/g, '');
  const nums = str.match(/\d+/g)?.map(Number) || [];
  if (str.includes('Below')) return { min: 0, max: nums[0], raw: val };
  if (str.includes('+')) return { min: nums[0], max: null, raw: val };
  if (nums.length === 2) return { min: nums[0], max: nums[1], raw: val };
  return { min: nums[0] || 0, max: null, raw: val };
}

// --- 2. TRANSFORMATION ENGINE ---
const results = [];
const now = new Date();

for (const item of $input.all()) {
  const raw = item.json.body || item.json.data || item.json;

  const budget = parseINR(raw.budget_inr);
  const formattedName = toTitleCase(clean(raw.full_name));

  // Handles multiple checkbox inputs for CRM-friendly strings
  const rawChallenges = raw.challenges || [];
  const challengesArray = Array.isArray(rawChallenges) ? rawChallenges : [rawChallenges];
  const challengesString = challengesArray.filter(Boolean).join(', ');

  results.push({
    json: {
      // Identity & Contact
      full_name: formattedName,
      first_name: formattedName.split(' ')[0] || '',
      last_name: formattedName.split(' ').slice(1).join(' ') || '',
      email: clean(raw.work_email)?.toLowerCase(),
      phone_normalized: formatPhone(raw.phone),

      // Company Intelligence
      company_name: clean(raw.company_name),
      company_website: sanitizeUrl(raw.company_website),
      company_size: raw.company_size || 'Not Specified',
      industry: raw.industry || 'Other',

      // Professional Persona
      job_role: clean(raw.job_role),
      decision_authority: raw.decision_power,

      // Intent & Pain Points
      primary_goal: raw.primary_goal,
      challenges: challengesString,
      timeline: raw.timeline,

      // Financials (Strict numeric for your separate Lead Scoring node)
      budget_numeric_min: budget.min,
      budget_numeric_max: budget.max,
      budget_display: budget.raw,

      // Compliance & Metadata
      notes: clean(raw.notes),
      consent_timestamp: now.toISOString(),
      lead_source: raw.source || 'sales_inquiry_form'
    }
  });
}

return results;

/**
 * LeadForge V6.3 - Production Hardened Extractor
 * Fixed: Handles AI math strings (e.g., "13 + 7 = 20") and JSON crashes.
 */

const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const rawOutput = data.output || ""; 
  let extractedScore = null;

  try {
    // 1. Find all JSON blocks (AI sometimes outputs multiple)
    const jsonMatches = rawOutput.match(/\{[\s\S]*?\}/g);
    const lastJson = jsonMatches ? jsonMatches[jsonMatches.length - 1] : null;

    if (lastJson) {
      // CLEANER: Remove math expressions like "10 + 5 = 15" inside the JSON
      // This prevents JSON.parse from crashing on non-numeric strings
      const cleanedJson = lastJson.replace(/:\s*\d+[\s\+\-\*\/=]+\d+[\s\+\-\*\/=]*\d*/g, (match) => {
          const numbers = match.match(/\d+/g);
          return `: ${numbers[numbers.length - 1]}`; // Keep only the final result
      });

      try {
        const parsed = JSON.parse(cleanedJson);
        if (parsed.hasOwnProperty('final_score')) {
          extractedScore = Number(parsed.final_score);
        } else if (parsed.hasOwnProperty('adjustment')) {
          extractedScore = Number(data.base_score || 0) + Number(parsed.adjustment);
        }
      } catch (e) {
        // If JSON is still malformed, fall through to Regex
      }
    }

    // 2. REGEX SAFETY NET (Hunts for the number in the prose)
    if (extractedScore === null || isNaN(extractedScore)) {
      // Look for the last occurrence of "score" followed by a number
      const scorePattern = /score[:\s=]*(\d+)/gi;
      let match;
      let lastValue = null;

      while ((match = scorePattern.exec(rawOutput)) !== null) {
        lastValue = Number(match[1]);
      }

      extractedScore = (lastValue !== null) ? lastValue : Number(data.base_score || 0);
    }

  } catch (err) {
    extractedScore = Number(data.base_score) || 0;
  }

  // 3. FINAL VALIDATION (Clamping 0-100)
  const finalValue = Math.min(100, Math.max(0, extractedScore));

  results.push({
    json: {
      ...data,
      final_score_numeric: Math.round(finalValue)
    }
  });
}

return results;

